-- ===== batch 3 =====
update known_safe_harbors set evidence_summary = 'Cytogenetic band 14q11.2. CRISPR/Cas9-mediated integration in primary human T cells -- "robust and consistent" CAR expression driven by the endogenous TRAC promoter. Dual benefit: the insertion disrupts the endogenous TCR, reducing graft-versus-host disease (GVHD) risk in allogeneic products. Sits in a transcriptionally active genomic environment, with no nearby oncogenic elements. Via secondary review, not verified against the primary article.', stability = 'Robust and consistent (duration not separately quantified)' where source_pmid = '41121349' and evidence_summary = 'Banda 14q11.2. Integração mediada por CRISPR/Cas9 em células T primárias humanas -- expressão de CAR "robusta e consistente" sob o promotor endógeno do TRAC. Benefício duplo: a inserção desativa o TCR endógeno, reduzindo risco de doença do enxerto-contra-hospedeiro (GVHD) em produtos alogénicos. Reside em ambiente genómico transcricionalmente ativo, sem elementos oncogénicos próximos. Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Cytogenetic band 14q11.2. CRISPR/Cas9-mediated integration in primary human T cells -- "robust and consistent" CAR expression driven by the endogenous TRAC promoter. Dual benefit: the insertion disrupts the endogenous TCR, reducing graft-versus-host disease (GVHD) risk in allogeneic products. Sits in a transcriptionally active genomic environment, with no nearby oncogenic elements. Via secondary review, not verified against the primary article.', stability = 'Robust and consistent (duration not separately quantified)' where source_pmid = '41121349' and evidence_summary = 'Banda 14q11.2. Integração mediada por CRISPR/Cas9 em células T primárias humanas -- expressão de CAR "robusta e consistente" sob o promotor endógeno do TRAC. Benefício duplo: a inserção desativa o TCR endógeno, reduzindo risco de doença do enxerto-contra-hospedeiro (GVHD) em produtos alogénicos. Reside em ambiente genómico transcricionalmente ativo, sem elementos oncogénicos próximos. Via review, não verificado contra artigo primário.';

update known_safe_harbors set evidence_summary = 'Chromosome not specified in the review. Anti-CD19 CAR T cells integrated at this locus showed potent antitumor activity in murine models of B-cell acute lymphoblastic leukemia, with efficacy comparable to the TRAC locus. Described as meeting all 8 GSH design criteria (including ncRNA protection and chromatin accessibility). Low confidence due to lack of a specific genomic location. Via secondary review, not verified against the primary article.', stability = 'Comparable efficacy to TRAC (duration not separately quantified)' where source_pmid = '41121349' and evidence_summary = 'Cromossoma não especificado na review. Células T CAR anti-CD19 integradas neste locus mostraram atividade antitumoral potente em modelos murinos de leucemia linfoblástica aguda B, com eficácia equiparável ao locus TRAC. Descrito como cumprindo os 8 critérios de desenho de GSH (incluindo proteção de ncRNA e acessibilidade de cromatina). Confiança baixa por falta de localização genómica específica. Via review, não verificado contra artigo primário.';
update public_safe_harbors_staging set evidence_summary = 'Chromosome not specified in the review. Anti-CD19 CAR T cells integrated at this locus showed potent antitumor activity in murine models of B-cell acute lymphoblastic leukemia, with efficacy comparable to the TRAC locus. Described as meeting all 8 GSH design criteria (including ncRNA protection and chromatin accessibility). Low confidence due to lack of a specific genomic location. Via secondary review, not verified against the primary article.', stability = 'Comparable efficacy to TRAC (duration not separately quantified)' where source_pmid = '41121349' and evidence_summary = 'Cromossoma não especificado na review. Células T CAR anti-CD19 integradas neste locus mostraram atividade antitumoral potente em modelos murinos de leucemia linfoblástica aguda B, com eficácia equiparável ao locus TRAC. Descrito como cumprindo os 8 critérios de desenho de GSH (incluindo proteção de ncRNA e acessibilidade de cromatina). Confiança baixa por falta de localização genómica específica. Via review, não verificado contra artigo primário.';

-- ===== batch 4 =====
update known_safe_harbors set evidence_summary = 'The Tigre locus (Igs7) used as a safe harbor in mouse macrophages (RAW 264.7) alongside ROSA26 for endogenous fluorescent knock-ins, and in mouse lines with a TRE-loxP system for intersectional expression in cerebellum and limbs. Established as an alternative to ROSA26, not merely theoretical.', stability = 'Established alternative to ROSA26 (duration not separately quantified)' where source_pmid = '38841290' and evidence_summary = 'Locus Tigre (Igs7) usado como safe harbor em macrófagos de ratinho (RAW 264.7) lado a lado com ROSA26 para knock-ins fluorescentes endógenos, e em linhas de ratinho com sistema TRE-loxP para expressão intersecional no cerebelo e membros. Estabelecido como alternativa a ROSA26, não apenas teórico.';
update public_safe_harbors_staging set evidence_summary = 'The Tigre locus (Igs7) used as a safe harbor in mouse macrophages (RAW 264.7) alongside ROSA26 for endogenous fluorescent knock-ins, and in mouse lines with a TRE-loxP system for intersectional expression in cerebellum and limbs. Established as an alternative to ROSA26, not merely theoretical.', stability = 'Established alternative to ROSA26 (duration not separately quantified)' where source_pmid = '38841290' and evidence_summary = 'Locus Tigre (Igs7) usado como safe harbor em macrófagos de ratinho (RAW 264.7) lado a lado com ROSA26 para knock-ins fluorescentes endógenos, e em linhas de ratinho com sistema TRE-loxP para expressão intersecional no cerebelo e membros. Estabelecido como alternativa a ROSA26, não apenas teórico.';

update known_safe_harbors set evidence_summary = 'The Hprt1 locus (X-linked) used for single-copy integration of a Cas9 transgene (Gdf9-Cas9) -- chosen precisely because it is a well-defined integration site that "does not influence transgene expression". Genome editing mediated by the transgenic Cas9 was as efficient as exogenous Cas9.', stability = 'Chosen for not influencing transgene expression (duration not separately quantified)' where source_pmid = '38523431' and evidence_summary = 'Locus Hprt1 (ligado ao X) usado para integração de cópia única de um transgene Cas9 (Gdf9-Cas9) -- selecionado precisamente por ser um sítio de integração bem definido que "não influencia a expressão do transgene". Edição genómica mediada pelo Cas9 transgénico tão eficiente como Cas9 exógeno.';
update public_safe_harbors_staging set evidence_summary = 'The Hprt1 locus (X-linked) used for single-copy integration of a Cas9 transgene (Gdf9-Cas9) -- chosen precisely because it is a well-defined integration site that "does not influence transgene expression". Genome editing mediated by the transgenic Cas9 was as efficient as exogenous Cas9.', stability = 'Chosen for not influencing transgene expression (duration not separately quantified)' where source_pmid = '38523431' and evidence_summary = 'Locus Hprt1 (ligado ao X) usado para integração de cópia única de um transgene Cas9 (Gdf9-Cas9) -- selecionado precisamente por ser um sítio de integração bem definido que "não influencia a expressão do transgene". Edição genómica mediada pelo Cas9 transgénico tão eficiente como Cas9 exógeno.';

update known_safe_harbors set evidence_summary = 'In human HAP1 cells, expression of auxin-binding F-box receptor proteins (AFB) from a transgene tends to decline with passaging in the absence of constant antibiotic selection -- does not prevent epigenetic silencing of the transgene even at the AAVS1 locus.', stability = 'Declines with passaging without selection pressure' where source_pmid = '34805274' and evidence_summary = 'Em células HAP1 humanas, expressão de proteínas F-box recetoras de auxina (AFB) a partir de transgene tende a declinar com as passagens na ausência de seleção antibiótica constante -- não previne silenciamento epigenético do transgene mesmo estando no locus AAVS1.';
update public_safe_harbors_staging set evidence_summary = 'In human HAP1 cells, expression of auxin-binding F-box receptor proteins (AFB) from a transgene tends to decline with passaging in the absence of constant antibiotic selection -- does not prevent epigenetic silencing of the transgene even at the AAVS1 locus.', stability = 'Declines with passaging without selection pressure' where source_pmid = '34805274' and evidence_summary = 'Em células HAP1 humanas, expressão de proteínas F-box recetoras de auxina (AFB) a partir de transgene tende a declinar com as passagens na ausência de seleção antibiótica constante -- não previne silenciamento epigenético do transgene mesmo estando no locus AAVS1.';

update known_safe_harbors set evidence_summary = 'Important finding: dCas9-VPR (CRISPRa) targeted to AAVS1 in hiPSCs activates target genes well during pluripotency, but silences after differentiation into cardiomyocytes and endothelium -- in direct CONTRAST with simple fluorescent proteins in the same construct/locus, which remain expressed. Silencing is payload-dependent, not just locus-dependent.', stability = 'Active during pluripotency; silences after cardiomyocyte/endothelial differentiation (payload-dependent)' where source_pmid = '38372898' and evidence_summary = 'Achado importante: dCas9-VPR (CRISPRa) alvejado a AAVS1 em hiPSCs ativa genes-alvo bem durante pluripotência, mas silencia após diferenciação em cardiomiócitos e endotélio -- em CONTRASTE direto com proteínas fluorescentes simples na mesma construção/locus, que permanecem expressas. O silenciamento é dependente da carga (payload), não só do locus.';
update public_safe_harbors_staging set evidence_summary = 'Important finding: dCas9-VPR (CRISPRa) targeted to AAVS1 in hiPSCs activates target genes well during pluripotency, but silences after differentiation into cardiomyocytes and endothelium -- in direct CONTRAST with simple fluorescent proteins in the same construct/locus, which remain expressed. Silencing is payload-dependent, not just locus-dependent.', stability = 'Active during pluripotency; silences after cardiomyocyte/endothelial differentiation (payload-dependent)' where source_pmid = '38372898' and evidence_summary = 'Achado importante: dCas9-VPR (CRISPRa) alvejado a AAVS1 em hiPSCs ativa genes-alvo bem durante pluripotência, mas silencia após diferenciação em cardiomiócitos e endotélio -- em CONTRASTE direto com proteínas fluorescentes simples na mesma construção/locus, que permanecem expressas. O silenciamento é dependente da carga (payload), não só do locus.';

update known_safe_harbors set evidence_summary = 'Same comparative study: dCas9-VPR targeted to hROSA26 also silences after differentiation into cardiomyocytes/endothelium, despite working well during pluripotency -- same pattern as AAVS1 and CLYBL in the same study. Reinforces that the payload (dCas9-VPR vs. a fluorescent reporter) is the determining factor for silencing, not the chosen locus.', stability = 'Active during pluripotency; silences after cardiomyocyte/endothelial differentiation (payload-dependent)' where source_pmid = '38372898' and evidence_summary = 'Mesmo estudo comparativo: dCas9-VPR alvejado a hROSA26 também silencia após diferenciação para cardiomiócitos/endotélio, apesar de funcionar bem durante pluripotência -- mesmo padrão que AAVS1 e CLYBL no mesmo estudo. Reforça que a carga (dCas9-VPR vs. repórter fluorescente) é o fator determinante de silenciamento, não o locus escolhido.';
update public_safe_harbors_staging set evidence_summary = 'Same comparative study: dCas9-VPR targeted to hROSA26 also silences after differentiation into cardiomyocytes/endothelium, despite working well during pluripotency -- same pattern as AAVS1 and CLYBL in the same study. Reinforces that the payload (dCas9-VPR vs. a fluorescent reporter) is the determining factor for silencing, not the chosen locus.', stability = 'Active during pluripotency; silences after cardiomyocyte/endothelial differentiation (payload-dependent)' where source_pmid = '38372898' and evidence_summary = 'Mesmo estudo comparativo: dCas9-VPR alvejado a hROSA26 também silencia após diferenciação para cardiomiócitos/endotélio, apesar de funcionar bem durante pluripotência -- mesmo padrão que AAVS1 e CLYBL no mesmo estudo. Reforça que a carga (dCas9-VPR vs. repórter fluorescente) é o fator determinante de silenciamento, não o locus escolhido.';

update known_safe_harbors set evidence_summary = 'Same comparative study: dCas9-VPR targeted to CLYBL also silences after differentiation into cardiomyocytes/endothelium, even though CLYBL is generally considered the best-performing locus among the three tested in this article. Reinforces that payload (not locus) determines silencing in this case.', stability = 'Active during pluripotency; silences after cardiomyocyte/endothelial differentiation (payload-dependent)' where source_pmid = '38372898' and evidence_summary = 'Mesmo estudo comparativo: dCas9-VPR alvejado a CLYBL também silencia após diferenciação para cardiomiócitos/endotélio, apesar do CLYBL ser geralmente considerado o locus com melhor desempenho de entre os três testados neste artigo. Reforça que o payload (não o locus) determina o silenciamento neste caso.';
update public_safe_harbors_staging set evidence_summary = 'Same comparative study: dCas9-VPR targeted to CLYBL also silences after differentiation into cardiomyocytes/endothelium, even though CLYBL is generally considered the best-performing locus among the three tested in this article. Reinforces that payload (not locus) determines silencing in this case.', stability = 'Active during pluripotency; silences after cardiomyocyte/endothelial differentiation (payload-dependent)' where source_pmid = '38372898' and evidence_summary = 'Mesmo estudo comparativo: dCas9-VPR alvejado a CLYBL também silencia após diferenciação para cardiomiócitos/endotélio, apesar do CLYBL ser geralmente considerado o locus com melhor desempenho de entre os três testados neste artigo. Reforça que o payload (não o locus) determina o silenciamento neste caso.';

-- ===== batch 5 =====
update known_safe_harbors set evidence_summary = 'FE-FVIII variant (hemophilia A) inserted at AAVS1 via Cas9(D10A) nickase in patient-derived iPSCs. Expressed in undifferentiated iPSCs AND in differentiated endothelial cells. HA mice transplanted with these ECs: 2.12x increase in blood FVIII activity, ~20% higher post-hemorrhage survival, effect maintained >3 months after subcutaneous transplant.', stability = 'Maintained >3 months post-transplant in vivo' where source_pmid = '39762408' and evidence_summary = 'Variante FE-FVIII (hemofilia A) inserida em AAVS1 via nickase Cas9(D10A) em iPSCs derivadas de doente. Expressa em iPSCs indiferenciadas E em células endoteliais diferenciadas. Ratinhos HA transplantados com estas ECs: aumento de 2.12x na atividade de FVIII no sangue, ~20% maior sobrevivência pós-hemorragia, efeito mantido >3 meses após transplante subcutâneo.';
update public_safe_harbors_staging set evidence_summary = 'FE-FVIII variant (hemophilia A) inserted at AAVS1 via Cas9(D10A) nickase in patient-derived iPSCs. Expressed in undifferentiated iPSCs AND in differentiated endothelial cells. HA mice transplanted with these ECs: 2.12x increase in blood FVIII activity, ~20% higher post-hemorrhage survival, effect maintained >3 months after subcutaneous transplant.', stability = 'Maintained >3 months post-transplant in vivo' where source_pmid = '39762408' and evidence_summary = 'Variante FE-FVIII (hemofilia A) inserida em AAVS1 via nickase Cas9(D10A) em iPSCs derivadas de doente. Expressa em iPSCs indiferenciadas E em células endoteliais diferenciadas. Ratinhos HA transplantados com estas ECs: aumento de 2.12x na atividade de FVIII no sangue, ~20% maior sobrevivência pós-hemorragia, efeito mantido >3 meses após transplante subcutâneo.';

update known_safe_harbors set evidence_summary = 'ChR2 (channelrhodopsin-2) inserted at AAVS1 in hPSCs, differentiated into forebrain organoids. Homogeneous, stable expression throughout the region, without structural/functional disruption, robust and consistent light-driven neuronal activation. Directly relevant to neuronal contexts.', stability = 'Stable and homogeneous through organoid differentiation' where source_pmid = '39545087' and evidence_summary = 'ChR2 (canalrodopsina-2) inserido em AAVS1 em hPSCs, diferenciadas em organoides de cérebro anterior. Expressão homogénea e estável em toda a região, sem perturbação estrutural/funcional, ativação neuronal robusta e consistente por luz. Diretamente relevante a contextos neuronais.';
update public_safe_harbors_staging set evidence_summary = 'ChR2 (channelrhodopsin-2) inserted at AAVS1 in hPSCs, differentiated into forebrain organoids. Homogeneous, stable expression throughout the region, without structural/functional disruption, robust and consistent light-driven neuronal activation. Directly relevant to neuronal contexts.', stability = 'Stable and homogeneous through organoid differentiation' where source_pmid = '39545087' and evidence_summary = 'ChR2 (canalrodopsina-2) inserido em AAVS1 em hPSCs, diferenciadas em organoides de cérebro anterior. Expressão homogénea e estável em toda a região, sem perturbação estrutural/funcional, ativação neuronal robusta e consistente por luz. Diretamente relevante a contextos neuronais.';

update known_safe_harbors set evidence_summary = 'In Jurkat T cells, a transgene at AAVS1 does not silence up to 160 days -- but expression shows huge transcriptional variation, over two orders of magnitude (100x) between cells, measured by barcoding + single-cell next-generation sequencing. Does not silence, but is highly heterogeneous in magnitude.', stability = 'No silencing through 160 days; high cell-to-cell expression variability' where source_pmid = '35795775' and evidence_summary = 'Em células Jurkat T, transgene em AAVS1 não silencia até 160 dias -- mas a expressão mostra variação transcricional grande, mais de duas ordens de grandeza (100x) entre células, medida por barcoding + sequenciação de próxima geração ao nível de célula única. Não silencia, mas é muito heterogéneo em magnitude.';
update public_safe_harbors_staging set evidence_summary = 'In Jurkat T cells, a transgene at AAVS1 does not silence up to 160 days -- but expression shows huge transcriptional variation, over two orders of magnitude (100x) between cells, measured by barcoding + single-cell next-generation sequencing. Does not silence, but is highly heterogeneous in magnitude.', stability = 'No silencing through 160 days; high cell-to-cell expression variability' where source_pmid = '35795775' and evidence_summary = 'Em células Jurkat T, transgene em AAVS1 não silencia até 160 dias -- mas a expressão mostra variação transcricional grande, mais de duas ordens de grandeza (100x) entre células, medida por barcoding + sequenciação de próxima geração ao nível de célula única. Não silencia, mas é muito heterogéneo em magnitude.';

update known_safe_harbors set evidence_summary = 'Correction of p47phox deficiency (chronic granulomatous disease) via AAVS1 in iPSCs, testing 3 myeloid-specific promoters after differentiation: miR223 and CatG/cFes gave therapeutically relevant expression; the MRP8 promoter was much less efficient due to high CpG methylation in differentiated cells. Silencing depends strongly on the chosen promoter, not just the locus.', stability = 'Promoter-dependent silencing after myeloid differentiation' where source_pmid = '31773990' and evidence_summary = 'Correção de deficiência p47phox (doença granulomatosa crónica) via AAVS1 em iPSCs, testando 3 promotores específicos de mieloides após diferenciação: miR223 e CatG/cFes deram expressão terapeuticamente relevante; promotor MRP8 foi muito menos eficiente devido a alta metilação CpG em células diferenciadas. Silenciamento depende fortemente do promotor escolhido, não só do locus.';
update public_safe_harbors_staging set evidence_summary = 'Correction of p47phox deficiency (chronic granulomatous disease) via AAVS1 in iPSCs, testing 3 myeloid-specific promoters after differentiation: miR223 and CatG/cFes gave therapeutically relevant expression; the MRP8 promoter was much less efficient due to high CpG methylation in differentiated cells. Silencing depends strongly on the chosen promoter, not just the locus.', stability = 'Promoter-dependent silencing after myeloid differentiation' where source_pmid = '31773990' and evidence_summary = 'Correção de deficiência p47phox (doença granulomatosa crónica) via AAVS1 em iPSCs, testando 3 promotores específicos de mieloides após diferenciação: miR223 e CatG/cFes deram expressão terapeuticamente relevante; promotor MRP8 foi muito menos eficiente devido a alta metilação CpG em células diferenciadas. Silenciamento depende fortemente do promotor escolhido, não só do locus.';

update known_safe_harbors set evidence_summary = 'Title of the article itself: identifies AAVS1 as "not an entirely safe harbour". Of 24 targeted hiPSC clones, only 20 expressed the transgene, ranging 0-99.5% positive cells. During differentiation into cardiomyocytes, silencing was observed: 98.93% -> 1.3% positive cells in one clone. A doxycycline-inducible system showed up to a 10,000x drop within 8-10 days. Expression only rescued with continuous puromycin selection.', stability = 'Silencing observed after cardiomyocyte differentiation; dox-inducible construct dropped up to 10,000x in 8-10 days' where source_pmid = '32789000' and evidence_summary = 'Título do próprio paper: "identifies the AAVS1 locus as not an entirely safe harbour". De 24 clones hiPSC alvejados, só 20 expressaram o transgene, variando 0-99.5% de células positivas. Durante diferenciação em cardiomiócitos, silenciamento observado: 98.93% -> 1.3% de células positivas num dos clones. Sistema indutível por doxiciclina teve queda de até 10.000x em 8-10 dias. Expressão só resgatada com seleção contínua por puromicina.';
update public_safe_harbors_staging set evidence_summary = 'Title of the article itself: identifies AAVS1 as "not an entirely safe harbour". Of 24 targeted hiPSC clones, only 20 expressed the transgene, ranging 0-99.5% positive cells. During differentiation into cardiomyocytes, silencing was observed: 98.93% -> 1.3% positive cells in one clone. A doxycycline-inducible system showed up to a 10,000x drop within 8-10 days. Expression only rescued with continuous puromycin selection.', stability = 'Silencing observed after cardiomyocyte differentiation; dox-inducible construct dropped up to 10,000x in 8-10 days' where source_pmid = '32789000' and evidence_summary = 'Título do próprio paper: "identifies the AAVS1 locus as not an entirely safe harbour". De 24 clones hiPSC alvejados, só 20 expressaram o transgene, variando 0-99.5% de células positivas. Durante diferenciação em cardiomiócitos, silenciamento observado: 98.93% -> 1.3% de células positivas num dos clones. Sistema indutível por doxiciclina teve queda de até 10.000x em 8-10 dias. Expressão só resgatada com seleção contínua por puromicina.';

update known_safe_harbors set evidence_summary = 'Transgenic mice carrying the human AAVS1 target sequence, tested with in vivo hematopoietic stem cell (HSC) transduction using HDAd5/35++ vectors. On average >60% of peripheral blood cells expressed the transgene after in vivo selection -- gamma-globin expression significantly higher and more stable than with random integration (SB100x-transposase system) used as a comparator in the same study.', stability = 'Higher and more stable expression than random integration comparator' where source_pmid = '31494053' and evidence_summary = 'Ratinhos transgénicos portadores da sequência humana AAVS1 como alvo, testados com transdução de células estaminais hematopoiéticas (HSC) in vivo com vetores HDAd5/35++. Em média >60% das células sanguíneas periféricas expressaram o transgene após seleção in vivo -- expressão de gama-globina significativamente mais alta e mais estável do que com integração aleatória (sistema SB100x-transposase) usado como comparador no mesmo estudo.';
update public_safe_harbors_staging set evidence_summary = 'Transgenic mice carrying the human AAVS1 target sequence, tested with in vivo hematopoietic stem cell (HSC) transduction using HDAd5/35++ vectors. On average >60% of peripheral blood cells expressed the transgene after in vivo selection -- gamma-globin expression significantly higher and more stable than with random integration (SB100x-transposase system) used as a comparator in the same study.', stability = 'Higher and more stable expression than random integration comparator' where source_pmid = '31494053' and evidence_summary = 'Ratinhos transgénicos portadores da sequência humana AAVS1 como alvo, testados com transdução de células estaminais hematopoiéticas (HSC) in vivo com vetores HDAd5/35++. Em média >60% das células sanguíneas periféricas expressaram o transgene após seleção in vivo -- expressão de gama-globina significativamente mais alta e mais estável do que com integração aleatória (sistema SB100x-transposase) usado como comparador no mesmo estudo.';

update known_safe_harbors set evidence_summary = 'H11-albumin-rtTA mice (albumin promoter driving rtTA at the H11 locus) -- liver-exclusive, doxycycline-inducible expression, confirmed by crossing with a TetO-H2BGFP reporter. Cre-mediated recombination as efficient as the conventional Albumin-Cre control. Reporter expression detectable already from embryonic stage E16.5 when induced.', stability = 'Detectable from embryonic stage E16.5; efficient recombination' where source_pmid = '30591434' and evidence_summary = 'Ratinhos H11-albumin-rtTA (promotor albumin a controlar rtTA no locus H11) -- expressão exclusivamente hepática e indutível por doxiciclina, confirmada por cruzamento com repórter TetO-H2BGFP. Recombinação mediada por Cre tão eficiente quanto o controlo Albumin-Cre convencional. Expressão do repórter detetável já a partir do estádio embrionário E16.5 quando induzido.';
update public_safe_harbors_staging set evidence_summary = 'H11-albumin-rtTA mice (albumin promoter driving rtTA at the H11 locus) -- liver-exclusive, doxycycline-inducible expression, confirmed by crossing with a TetO-H2BGFP reporter. Cre-mediated recombination as efficient as the conventional Albumin-Cre control. Reporter expression detectable already from embryonic stage E16.5 when induced.', stability = 'Detectable from embryonic stage E16.5; efficient recombination' where source_pmid = '30591434' and evidence_summary = 'Ratinhos H11-albumin-rtTA (promotor albumin a controlar rtTA no locus H11) -- expressão exclusivamente hepática e indutível por doxiciclina, confirmada por cruzamento com repórter TetO-H2BGFP. Recombinação mediada por Cre tão eficiente quanto o controlo Albumin-Cre convencional. Expressão do repórter detetável já a partir do estádio embrionário E16.5 quando induzido.';

update known_safe_harbors set evidence_summary = 'Robust, reproducible CAG-promoter-driven expression at AAVS1 (PPP1R12C intron), with reproducible copy-number control between subclones (~2x). Expression maintained during long-term culture of human iPSCs and through differentiation into multiple lineages. Widely used protocol/methodology paper, commonly cited as a reference.', stability = 'Stable through long-term culture and multi-lineage differentiation' where source_pmid = '26707206' and evidence_summary = 'Expressão robusta e reprodutível guiada por promotor CAG em AAVS1 (intrão do gene PPP1R12C), com controlo de número de cópias reproduzível entre subclones (~2x). Expressão mantida durante cultura de longo prazo de iPSCs humanas e ao longo de diferenciação em múltiplas linhagens. Paper de protocolo/metodologia amplamente usado como referência.';
update public_safe_harbors_staging set evidence_summary = 'Robust, reproducible CAG-promoter-driven expression at AAVS1 (PPP1R12C intron), with reproducible copy-number control between subclones (~2x). Expression maintained during long-term culture of human iPSCs and through differentiation into multiple lineages. Widely used protocol/methodology paper, commonly cited as a reference.', stability = 'Stable through long-term culture and multi-lineage differentiation' where source_pmid = '26707206' and evidence_summary = 'Expressão robusta e reprodutível guiada por promotor CAG em AAVS1 (intrão do gene PPP1R12C), com controlo de número de cópias reproduzível entre subclones (~2x). Expressão mantida durante cultura de longo prazo de iPSCs humanas e ao longo de diferenciação em múltiplas linhagens. Paper de protocolo/metodologia amplamente usado como referência.';

update known_safe_harbors set evidence_summary = 'Explicit conclusion from the title itself: "AAVS1 Locus-Mediated Transgene Inhibition". Unexpected, variable expression inhibition observed both in undifferentiated hESCs and in differentiated hepatocytes, attributed to DNA methylation and other unknown mechanisms. Authors'' conclusion: "AAVS1 cannot be considered a universally safe harbor for reliable transgene expression in vitro".', stability = 'Variable inhibition in undifferentiated and differentiated cells' where source_pmid = '26455413' and evidence_summary = 'Conclusão explícita do próprio título: "AAVS1 Locus-Mediated Transgene Inhibition". Inibição de expressão inesperada e variável observada tanto em hESC indiferenciadas como em hepatócitos diferenciados, atribuída a metilação de DNA e outros mecanismos desconhecidos. Conclusão dos autores: "AAVS1 não pode ser considerado um safe harbor universalmente seguro para expressão fiável de transgene in vitro".';
update public_safe_harbors_staging set evidence_summary = 'Explicit conclusion from the title itself: "AAVS1 Locus-Mediated Transgene Inhibition". Unexpected, variable expression inhibition observed both in undifferentiated hESCs and in differentiated hepatocytes, attributed to DNA methylation and other unknown mechanisms. Authors'' conclusion: "AAVS1 cannot be considered a universally safe harbor for reliable transgene expression in vitro".', stability = 'Variable inhibition in undifferentiated and differentiated cells' where source_pmid = '26455413' and evidence_summary = 'Conclusão explícita do próprio título: "AAVS1 Locus-Mediated Transgene Inhibition". Inibição de expressão inesperada e variável observada tanto em hESC indiferenciadas como em hepatócitos diferenciados, atribuída a metilação de DNA e outros mecanismos desconhecidos. Conclusão dos autores: "AAVS1 não pode ser considerado um safe harbor universalmente seguro para expressão fiável de transgene in vitro".';

update known_safe_harbors set evidence_summary = 'Promoter comparison within the ROSA26 locus itself in mouse ES cells: direct expression from the endogenous ROSA26 promoter gives a moderate level; inserting a CAGG promoter at the ROSA26 locus gives higher expression. Expression level at ROSA26 depends strongly on the promoter used, not just the choice of locus.', stability = 'Promoter-dependent expression level (duration not separately quantified)' where source_pmid = '19279185' and evidence_summary = 'Comparação de promotores dentro do próprio locus ROSA26 em ES de ratinho: expressão direta pelo promotor ROSA26 endógeno dá nível moderado; inserir um promotor CAGG no locus ROSA26 dá expressão mais alta. O nível de expressão em ROSA26 depende fortemente do promotor usado, não só da escolha do locus.';
update public_safe_harbors_staging set evidence_summary = 'Promoter comparison within the ROSA26 locus itself in mouse ES cells: direct expression from the endogenous ROSA26 promoter gives a moderate level; inserting a CAGG promoter at the ROSA26 locus gives higher expression. Expression level at ROSA26 depends strongly on the promoter used, not just the choice of locus.', stability = 'Promoter-dependent expression level (duration not separately quantified)' where source_pmid = '19279185' and evidence_summary = 'Comparação de promotores dentro do próprio locus ROSA26 em ES de ratinho: expressão direta pelo promotor ROSA26 endógeno dá nível moderado; inserir um promotor CAGG no locus ROSA26 dá expressão mais alta. O nível de expressão em ROSA26 depende fortemente do promotor usado, não só da escolha do locus.';

update known_safe_harbors set evidence_summary = 'Founding paper identifying the human homolog of the mouse ROSA26 locus. tdRFP targeted by homologous recombination was expressed across multiple hESC-derived lineages. Recombinase-mediated cassette exchange (RMCE) demonstrated to swap the transgene for other cDNAs at the same locus.', stability = 'Expressed across multiple derived lineages (duration not quantified)' where source_pmid = '18037879' and evidence_summary = 'Paper fundador da identificação do homólogo humano do locus ROSA26 de ratinho. tdRFP alvejado por recombinação homóloga expressou-se em múltiplas linhagens derivadas de hESC. Demonstrada troca de cassete mediada por recombinase (RMCE) para trocar o transgene por outros cDNAs no mesmo locus.';
update public_safe_harbors_staging set evidence_summary = 'Founding paper identifying the human homolog of the mouse ROSA26 locus. tdRFP targeted by homologous recombination was expressed across multiple hESC-derived lineages. Recombinase-mediated cassette exchange (RMCE) demonstrated to swap the transgene for other cDNAs at the same locus.', stability = 'Expressed across multiple derived lineages (duration not quantified)' where source_pmid = '18037879' and evidence_summary = 'Paper fundador da identificação do homólogo humano do locus ROSA26 de ratinho. tdRFP alvejado por recombinação homóloga expressou-se em múltiplas linhagens derivadas de hESC. Demonstrada troca de cassete mediada por recombinase (RMCE) para trocar o transgene por outros cDNAs no mesmo locus.';

update known_safe_harbors set evidence_summary = 'Founding paper (2007), direct quantified comparison with random integration: with selection, 90+-4% positive cells at AAVS1 vs. 57+-32% with random integration; 25 days after removing selection, 86+-7% vs. only 39+-31% (random) -- i.e. much more resistant to silencing. After 15 days of differentiation, >90% (AAVS1) vs. ~30% (random) still positive. One of the most cited papers in the field.', stability = 'Stable >25 days post-selection and >15 days into differentiation; markedly more resistant to silencing than random integration' where source_pmid = '18024421' and evidence_summary = 'Paper fundador (2007), comparação direta e quantificada com integração aleatória: com seleção, 90+-4% de células positivas em AAVS1 vs. 57+-32% em integração aleatória; 25 dias após remoção da seleção, 86+-7% vs. apenas 39+-31% (aleatória) -- ou seja, muito mais resistente a silenciamento. Após 15 dias de diferenciação, >90% (AAVS1) vs. ~30% (aleatória) ainda positivas. Um dos papers mais citados da área.';
update public_safe_harbors_staging set evidence_summary = 'Founding paper (2007), direct quantified comparison with random integration: with selection, 90+-4% positive cells at AAVS1 vs. 57+-32% with random integration; 25 days after removing selection, 86+-7% vs. only 39+-31% (random) -- i.e. much more resistant to silencing. After 15 days of differentiation, >90% (AAVS1) vs. ~30% (random) still positive. One of the most cited papers in the field.', stability = 'Stable >25 days post-selection and >15 days into differentiation; markedly more resistant to silencing than random integration' where source_pmid = '18024421' and evidence_summary = 'Paper fundador (2007), comparação direta e quantificada com integração aleatória: com seleção, 90+-4% de células positivas em AAVS1 vs. 57+-32% em integração aleatória; 25 dias após remoção da seleção, 86+-7% vs. apenas 39+-31% (aleatória) -- ou seja, muito mais resistente a silenciamento. Após 15 dias de diferenciação, >90% (AAVS1) vs. ~30% (aleatória) ainda positivas. Um dos papers mais citados da área.';

-- ===== batch 6 =====
update known_safe_harbors set locus_name = 'GSH6', evidence_summary = 'Extragenic locus identified by a proprietary algorithm (7 criteria to minimize genotoxicity and maximize CRISPR/Cas9 efficiency and resistance to silencing). CAR-CD19 T cells built at GSH6 were curative at a low cell dose in a murine acute lymphoblastic leukemia model, matching the potency of CAR-T cells built at the TRAC locus, and resisting tumor rechallenge 100 days after infusion. Substantially stronger data than the brief mention found earlier via secondary review -- this is the primary paper.', stability = 'Curative and durable to 100-day tumor rechallenge in vivo' where source_pmid = '36745870' and evidence_summary = 'Locus extragénico identificado por algoritmo próprio (7 critérios para minimizar genotoxicidade e maximizar eficiência CRISPR/Cas9 e resistência a silenciamento). Células T CAR-CD19 construídas em GSH6 foram curativas a dose celular baixa em modelo murino de leucemia linfoblástica aguda, igualando a potência de CAR-T construídas no locus TRAC, e resistindo a re-desafio tumoral 100 dias após infusão. Dados substancialmente mais fortes que a menção breve encontrada antes via review secundária -- este é o paper primário.';
update public_safe_harbors_staging set locus_name = 'GSH6', evidence_summary = 'Extragenic locus identified by a proprietary algorithm (7 criteria to minimize genotoxicity and maximize CRISPR/Cas9 efficiency and resistance to silencing). CAR-CD19 T cells built at GSH6 were curative at a low cell dose in a murine acute lymphoblastic leukemia model, matching the potency of CAR-T cells built at the TRAC locus, and resisting tumor rechallenge 100 days after infusion. Substantially stronger data than the brief mention found earlier via secondary review -- this is the primary paper.', stability = 'Curative and durable to 100-day tumor rechallenge in vivo' where source_pmid = '36745870' and evidence_summary = 'Locus extragénico identificado por algoritmo próprio (7 critérios para minimizar genotoxicidade e maximizar eficiência CRISPR/Cas9 e resistência a silenciamento). Células T CAR-CD19 construídas em GSH6 foram curativas a dose celular baixa em modelo murino de leucemia linfoblástica aguda, igualando a potência de CAR-T construídas no locus TRAC, e resistindo a re-desafio tumoral 100 dias após infusão. Dados substancialmente mais fortes que a menção breve encontrada antes via review secundária -- este é o paper primário.';

update known_safe_harbors set evidence_summary = 'Additional detail on a locus already registered: transgene-encoded Cas9 proteins at SHS231 (chromosome 4) used to introduce a large (17kb) gRNA-guided deletion in the PAX3/FOXO1 fusion oncogene in human rhabdomyosarcoma cells, and as a Cas9-VPR fusion to activate the muscle transcription factor MYF5. Confirms transgene function, not just expression, at this locus.', stability = 'Functional (not just expressed) at this locus' where source_pmid = '30793977' and evidence_summary = 'Detalhe adicional ao já registado: proteínas Cas9 codificadas por transgene em SHS231 (cromossoma 4) usadas para introduzir uma deleção grande (17kb) guiada por gRNA no oncogene de fusão PAX3/FOXO1 em células de rabdomiossarcoma humano, e como fusão Cas9-VPR para ativar o fator de transcrição muscular MYF5. Confirma função, não só expressão, do transgene neste locus.';
update public_safe_harbors_staging set evidence_summary = 'Additional detail on a locus already registered: transgene-encoded Cas9 proteins at SHS231 (chromosome 4) used to introduce a large (17kb) gRNA-guided deletion in the PAX3/FOXO1 fusion oncogene in human rhabdomyosarcoma cells, and as a Cas9-VPR fusion to activate the muscle transcription factor MYF5. Confirms transgene function, not just expression, at this locus.', stability = 'Functional (not just expressed) at this locus' where source_pmid = '30793977' and evidence_summary = 'Detalhe adicional ao já registado: proteínas Cas9 codificadas por transgene em SHS231 (cromossoma 4) usadas para introduzir uma deleção grande (17kb) guiada por gRNA no oncogene de fusão PAX3/FOXO1 em células de rabdomiossarcoma humano, e como fusão Cas9-VPR para ativar o fator de transcrição muscular MYF5. Confirma função, não só expressão, do transgene neste locus.';

update known_safe_harbors set evidence_summary = 'An under-discussed safety consideration: the AAVS1 locus includes the coding region of the MBS85 gene (myosin binding subunit 85). Transgene insertion at AAVS1 significantly reduces MBS85 expression and alters myosin-II-dependent contractile force in human fibroblasts (via phosphorylation of the myosin regulatory light chain) -- effect reversed by restoring MBS85 expression. A real effect on a neighboring gene, not just a theoretical one.', stability = 'Real functional side-effect on neighboring gene, independent of transgene silencing/duration' where source_pmid = '26260320' and evidence_summary = 'Consideração de segurança pouco discutida: o locus AAVS1 inclui a região codificante do gene MBS85 (myosin binding subunit 85). Inserção de transgene em AAVS1 reduz significativamente a expressão de MBS85 e altera a força contráctil dependente de miosina II em fibroblastos humanos (via fosforilação da cadeia leve reguladora de miosina) -- efeito revertido ao restaurar expressão de MBS85. Efeito real no gene vizinho, não apenas teórico.';
update public_safe_harbors_staging set evidence_summary = 'An under-discussed safety consideration: the AAVS1 locus includes the coding region of the MBS85 gene (myosin binding subunit 85). Transgene insertion at AAVS1 significantly reduces MBS85 expression and alters myosin-II-dependent contractile force in human fibroblasts (via phosphorylation of the myosin regulatory light chain) -- effect reversed by restoring MBS85 expression. A real effect on a neighboring gene, not just a theoretical one.', stability = 'Real functional side-effect on neighboring gene, independent of transgene silencing/duration' where source_pmid = '26260320' and evidence_summary = 'Consideração de segurança pouco discutida: o locus AAVS1 inclui a região codificante do gene MBS85 (myosin binding subunit 85). Inserção de transgene em AAVS1 reduz significativamente a expressão de MBS85 e altera a força contráctil dependente de miosina II em fibroblastos humanos (via fosforilação da cadeia leve reguladora de miosina) -- efeito revertido ao restaurar expressão de MBS85. Efeito real no gene vizinho, não apenas teórico.';

update known_safe_harbors set evidence_summary = 'AAVS1-targeted (ZFN) minigene platform to correct all 5 chronic granulomatous disease genotypes in patient-derived CD34+ iPSCs. Targeted insertion with constitutive expression in 70-80% of selected clones. Neutrophils and macrophages differentiated from these corrected iPSCs showed restored oxidase activity and functional antimicrobial activity against real bacterial pathogens.', stability = 'Constitutive expression in 70-80% of clones (duration not further quantified)' where source_pmid = '25288370' and evidence_summary = 'Plataforma de minigene alvejando AAVS1 (ZFN) para corrigir os 5 genótipos de doença granulomatosa crónica em iPSCs derivadas de CD34+ de doentes. Inserção alvejada com expressão constitutiva em 70-80% dos clones selecionados. Neutrófilos e macrófagos diferenciados destas iPSCs corrigidas mostraram atividade oxidase restaurada e função antimicrobiana funcional contra patogénios bacterianos reais.';
update public_safe_harbors_staging set evidence_summary = 'AAVS1-targeted (ZFN) minigene platform to correct all 5 chronic granulomatous disease genotypes in patient-derived CD34+ iPSCs. Targeted insertion with constitutive expression in 70-80% of selected clones. Neutrophils and macrophages differentiated from these corrected iPSCs showed restored oxidase activity and functional antimicrobial activity against real bacterial pathogens.', stability = 'Constitutive expression in 70-80% of clones (duration not further quantified)' where source_pmid = '25288370' and evidence_summary = 'Plataforma de minigene alvejando AAVS1 (ZFN) para corrigir os 5 genótipos de doença granulomatosa crónica em iPSCs derivadas de CD34+ de doentes. Inserção alvejada com expressão constitutiva em 70-80% dos clones selecionados. Neutrófilos e macrófagos diferenciados destas iPSCs corrigidas mostraram atividade oxidase restaurada e função antimicrobiana funcional contra patogénios bacterianos reais.';

update known_safe_harbors set evidence_summary = 'Two independent iPSC lines with a doxycycline-inducible NGN2 cassette (with and without GFP) inserted at AAVS1: remain pluripotent without doxycycline, differentiate rapidly and homogeneously into excitatory neurons when induced, with no need for additional differentiation factors.', stability = 'Pluripotent without induction; rapid homogeneous differentiation on induction' where source_pmid = '33610017' and evidence_summary = 'Duas linhas iPSC independentes com cassete NGN2 indutível por doxiciclina (com e sem GFP) inseridas em AAVS1: mantêm-se pluripotentes sem doxiciclina, diferenciam rápida e homogeneamente em neurónios excitatórios quando induzidas, sem necessidade de fatores de diferenciação adicionais.';
