update known_safe_harbors set evidence_summary = 'Equivalent/independent system: a doxycycline-inducible Neurogenin-2 (Ngn2) cassette inserted at AAVS1 by CRISPR/Cas9 in hiPSCs -- generates a cell line that differentiates rapidly and homogeneously into excitatory neurons.', stability = 'Rapid, homogeneous differentiation on induction' where source_pmid = '35696030' and evidence_summary = 'Sistema equivalente/independente ao anterior: cassete Neurogenin-2 (Ngn2) indutível inserida em AAVS1 por CRISPR/Cas9 em hiPSCs -- gera linha celular que diferencia rápida e homogeneamente em neurónios excitatórios.';
update public_safe_harbors_staging set evidence_summary = 'Equivalent/independent system: a doxycycline-inducible Neurogenin-2 (Ngn2) cassette inserted at AAVS1 by CRISPR/Cas9 in hiPSCs -- generates a cell line that differentiates rapidly and homogeneously into excitatory neurons.', stability = 'Rapid, homogeneous differentiation on induction' where source_pmid = '35696030' and evidence_summary = 'Sistema equivalente/independente ao anterior: cassete Neurogenin-2 (Ngn2) indutível inserida em AAVS1 por CRISPR/Cas9 em hiPSCs -- gera linha celular que diferencia rápida e homogeneamente em neurónios excitatórios.';

update known_safe_harbors set evidence_summary = 'CELiD vector (closed-ended double-stranded linear DNA, AAV-derived) used to integrate an anti-CD19 CAR directly at AAVS1 in primary human T cells -- integration efficiency up to 22.8%, resulting CAR-T cells produced abundant effector cytokines and killed up to 75% of target cells in vitro.', stability = 'Functional in vitro (duration not separately quantified)' where source_pmid = '31901177' and evidence_summary = 'Vetor CELiD (DNA linear de cadeia dupla com pontas fechadas, derivado de AAV) usado para integrar um CAR anti-CD19 diretamente em AAVS1 em células T primárias humanas -- eficiência de integração até 22.8%, células CAR-T resultantes produziram citocinas efetoras abundantes e mataram até 75% das células-alvo in vitro.';
